// HasResults applies the HasEdge predicate on the "results" edge.
func HasResults() predicate.IQCheckSite {
	return predicate.IQCheckSite(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ResultsTable, ResultsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasResultsWith applies the HasEdge predicate on the "results" edge with a given conditions (other predicates).
func HasResultsWith(preds ...predicate.IQCheckResult) predicate.IQCheckSite {
	return predicate.IQCheckSite(func(s *sql.Selector) {
		step := newResultsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IQCheckSite) predicate.IQCheckSite {
	return predicate.IQCheckSite(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IQCheckSite) predicate.IQCheckSite {
	return predicate.IQCheckSite(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IQCheckSite) predicate.IQCheckSite {
	return predicate.IQCheckSite(sql.NotPredicates(p))
}
